css:
*{box-sizing:border-box;margin:0;padding:0}
:root{
 --green-900:#122f22;--green-800:#183a2a;--green-700:#1f4a35;--green-600:#2e7d4f;--green-500:#3a9d63;
 --gold:#e0a72e;--gold-dark:#c8901f;--gold-soft:rgba(224,167,46,.14);
 --ink:#16241c;--body:#33413a;--muted:#6b7b72;--bg:#f6f8f4;--card:#fff;--line:#e3ebe3;
 --ring:rgba(46,125,79,.35);--shadow:0 10px 30px rgba(18,47,34,.10);--shadow-sm:0 2px 10px rgba(18,47,34,.06);
 --radius:16px;--gut:clamp(16px,4vw,40px);
 --font-body:"Inter",ui-sans-serif,system-ui,sans-serif;--font-display:"Poppins",var(--font-body);
}
html{scroll-behavior:smooth}
body{font-family:var(--font-body);color:var(--body);background:var(--bg);line-height:1.62;-webkit-font-smoothing:antialiased}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.15;font-weight:700}
.wrap{max-width:1200px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{display:inline-block;font-family:var(--font-display);font-weight:600;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;color:var(--green-600)}
.section{padding:clamp(48px,7vw,86px) 0}
.lead{font-size:1.08rem;color:var(--body)}
/* reveal (pure CSS, JS-safe) */
.rv{animation:rvIn .8s both}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;font-family:var(--font-display);font-weight:600;font-size:1rem;padding:.85em 1.5em;border-radius:999px;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,background .15s ease;text-align:center}
.btn:hover{transform:translateY(-2px)}
.btn-lime{background:var(--gold);color:#000;box-shadow:0 8px 22px rgba(224,167,46,.32)}
.btn-lime:hover{background:var(--gold-dark)}
.btn-primary{background:var(--gold);color:#000}
.btn-primary:hover{background:var(--gold-dark)}
.btn-outline{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-outline:hover{background:rgba(255,255,255,.12)}
.btn-ghost{background:rgba(255,255,255,.12);color:#fff;border-color:rgba(255,255,255,.4)}
.btn-ghost:hover{background:rgba(255,255,255,.2)}
.btn-block{width:100%}
.btn .ic-svg{width:16px;height:16px}
/* ---------- header ---------- */
header.site{position:sticky;top:0;z-index:900;background:rgba(246,248,244,.92);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1200px;margin:0 auto;padding:10px var(--gut);display:flex;align-items:center;gap:18px}
.hdr-logo img{height:60px;width:auto}
.hdr-spacer{flex:1}
.nav{display:flex;align-items:center;gap:6px}
.nav a,.nav .drop-lbl{font-family:var(--font-display);font-weight:600;font-size:.95rem;color:var(--ink);padding:.5em .7em;border-radius:10px;cursor:pointer;display:inline-flex;align-items:center;gap:4px}
.nav a:hover,.nav .drop-lbl:hover{background:var(--gold-soft);color:var(--green-700)}
.hdr-actions{display:flex;align-items:center;gap:10px}
.hdr-call{font-family:var(--font-display);font-weight:600;color:var(--green-700);white-space:nowrap}
.hdr-cta{background:var(--gold);color:#000;padding:.62em 1.1em;border-radius:999px;font-family:var(--font-display);font-weight:600;white-space:nowrap}
.hdr-cta:hover{background:var(--gold-dark)}
/* services dropdown (pure CSS) */
.has-drop{position:relative}
.drop-cb,.burger-cb{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.caret{font-size:.7em}
.drop{position:absolute;top:calc(100% + 6px);left:0;min-width:210px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:8px;display:none;flex-direction:column;gap:2px}
.drop a{font-size:.9rem;padding:.55em .7em;border-radius:9px}
.drop-cb:checked ~ .drop{display:flex}
.burger{display:none;font-size:1.7rem;line-height:1;color:var(--ink);cursor:pointer;padding:4px 8px;border-radius:10px}
/* mobile */
@media (max-width:960px){
 .burger{display:inline-flex}
 .hdr-call{display:none}
 .nav{position:absolute;top:100%;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);box-shadow:var(--shadow);flex-direction:column;align-items:stretch;gap:0;padding:10px var(--gut);clip-path:inset(0 0 100% 0);pointer-events:none;transition:clip-path .25s ease}
 .burger-cb:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
 .nav a,.nav .drop-lbl{padding:.8em .4em;border-radius:8px}
 .has-drop{position:static}
 .drop{position:static;box-shadow:none;border:none;border-left:2px solid var(--gold-soft);border-radius:0;margin:0 0 6px 12px;padding:2px 0 2px 10px}
}
/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;background:linear-gradient(160deg,var(--green-800) 0%,var(--green-700) 46%,var(--green-600) 100%);color:#fff}
.hero:before{content:"";position:absolute;inset:0;background:radial-gradient(1100px 460px at 82% -6%,rgba(224,167,46,.20),transparent 60%),radial-gradient(760px 420px at 0% 110%,rgba(58,157,99,.28),transparent 60%);pointer-events:none}
.hero-inner{position:relative;max-width:860px;padding:clamp(52px,8vw,104px) 0 clamp(44px,6vw,76px)}
.hero .eyebrow{color:var(--gold)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5.4vw,3.5rem);font-weight:800;margin:.35em 0 .3em}
.hero h1 .accent{color:var(--gold)}
.hero .sub{font-size:clamp(1.05rem,2vw,1.28rem);color:#eaf3ec;max-width:46ch;margin-bottom:.7em}
.hero .body-txt{color:#cfe0d4;max-width:52ch;margin-bottom:1.4em}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px}
.hero-mini{margin-top:1.1em;font-size:.9rem;color:#bcd2c2}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:2.2em;max-width:640px}
.stat{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:14px 12px}
.stat .num{font-family:var(--font-display);font-weight:800;font-size:1.5rem;color:var(--gold)}
.stat .lbl{font-size:.76rem;color:#cfe0d4;letter-spacing:.02em}
@media (max-width:560px){.stats{grid-template-columns:repeat(2,1fr)}}
/* ---------- intro ---------- */
.intro-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(24px,4vw,52px);align-items:center}
.intro-copy h2{font-size:clamp(1.5rem,3vw,2rem);margin-bottom:.5em}
.intro-copy p{margin-bottom:1em;min-width:0}
.intro-photo img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:var(--radius);box-shadow:var(--shadow)}
.intro-photo figcaption{font-size:.8rem;color:var(--muted);margin-top:8px;text-align:center}
@media (max-width:820px){.intro-grid{grid-template-columns:1fr}.intro-photo{order:-1}}
/* trust strip */
.trust{background:var(--green-900);color:#eaf3ec}
.trust .wrap{display:flex;flex-wrap:wrap;gap:10px 26px;justify-content:center;padding-top:16px;padding-bottom:16px}
.trust span{display:inline-flex;align-items:center;gap:8px;font-size:.92rem;font-weight:500}
.trust svg{color:var(--gold);width:16px;height:16px}
/* ---------- services cards ---------- */
.services-sec{background:linear-gradient(180deg,#fff,var(--bg))}
.sec-head{text-align:center;max-width:720px;margin:0 auto 34px}
.sec-head h2{font-size:clamp(1.6rem,3.2vw,2.15rem);margin-top:.25em}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
@media (max-width:980px){.cards{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.cards{grid-template-columns:1fr}}
.card{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--gold)}
.card .ico{width:46px;height:46px;border-radius:12px;background:var(--gold-soft);display:flex;align-items:center;justify-content:center;margin-bottom:14px}
.card .ico svg{width:24px;height:24px;color:var(--green-600)}
.card h3{font-size:1.08rem;margin-bottom:.4em}
.card p{font-size:.92rem;color:var(--muted);margin-bottom:14px}
.card-more{margin-top:auto;font-family:var(--font-display);font-weight:600;font-size:.88rem;color:var(--green-600);display:inline-flex;align-items:center;gap:6px}
.card-more svg{width:15px;height:15px;transition:transform .18s ease}
.card:hover .card-more{color:var(--green-700)}
.card:hover .card-more svg{transform:translateX(3px)}
/* ---------- why ---------- */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:30px}
@media (max-width:820px){.why-grid{grid-template-columns:1fr 1fr}}
@media (max-width:520px){.why-grid{grid-template-columns:1fr}}
.why-item{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px}
.why-item h3{display:flex;align-items:center;gap:10px;font-size:1.02rem;margin-bottom:.35em}
.check{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:50%;background:var(--green-600);color:#fff;font-size:.8rem;flex-shrink:0}
.why-item p{font-size:.9rem;color:var(--muted)}
/* ---------- local band ---------- */
.local{background:var(--green-800);color:#eaf3ec}
.local h2{color:#fff}
.local .eyebrow{color:var(--gold)}
.local-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:28px}
@media (max-width:820px){.local-grid{grid-template-columns:1fr}}
.local-card{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.13);border-radius:14px;padding:22px}
.local-card h3{color:#fff;font-size:1.06rem;margin-bottom:.4em}
.local-card p{font-size:.92rem;color:#cfe0d4}
/* ---------- quote form ---------- */
.form-wrap .wrap{max-width:640px}
.form-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:clamp(22px,4vw,34px)}
.field{margin-bottom:14px;min-width:0}
.field label{display:block;font-family:var(--font-display);font-weight:600;font-size:.86rem;margin-bottom:6px;color:var(--ink)}
.field input,.field select,.field textarea{width:100%;min-width:0;font-family:var(--font-body);font-size:1rem;padding:.7em .85em;border:1px solid var(--line);border-radius:12px;background:#fbfdfb;color:var(--ink)}
.field textarea{min-height:110px;resize:vertical}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--green-600);box-shadow:0 0 0 3px var(--ring)}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}
@media (max-width:520px){.grid-2{grid-template-columns:1fr}}
select option{background:#fff;color:var(--ink)}
.reassure{font-size:.82rem;color:var(--muted);text-align:center;margin-top:12px}
/* ---------- FAQ ---------- */
.faq-list{max-width:820px;margin:26px auto 0}
.faq{background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:12px;overflow:hidden}
.faq summary{list-style:none;cursor:pointer;padding:18px 22px;font-family:var(--font-display);font-weight:600;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:12px}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"+";font-size:1.4rem;color:var(--green-600);transition:transform .2s}
.faq[open] summary:after{content:"–"}
.faq .ans{padding:0 22px 18px;color:var(--body);font-size:.96rem}
/* ---------- zones (hub) ---------- */
.zones{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:30px}
@media (max-width:820px){.zones{grid-template-columns:1fr 1fr}}
@media (max-width:520px){.zones{grid-template-columns:1fr}}
.zone{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm)}
.zone h3{font-size:1.12rem;margin-bottom:.45em}
.zone p{font-size:.92rem;color:var(--muted);margin-bottom:.8em}
.zone .zlink{font-family:var(--font-display);font-weight:600;color:var(--green-600);font-size:.92rem;display:inline-flex;align-items:center;gap:6px}
.zone.cta-zone{background:linear-gradient(160deg,var(--green-700),var(--green-600));color:#fff}
.zone.cta-zone h3{color:#fff}
.loc-list{list-style:none;display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 0}
.loc-list a{background:var(--gold-soft);color:var(--green-700);font-weight:600;font-size:.88rem;padding:.4em .8em;border-radius:999px;font-family:var(--font-display)}
.loc-list a:hover{background:var(--gold);color:#000}
/* ---------- cta band ---------- */
.cta-band{background:linear-gradient(160deg,var(--green-700),var(--green-900));color:#fff;text-align:center}
.cta-band h2{color:#fff;font-size:clamp(1.6rem,3.4vw,2.3rem);max-width:20ch;margin:0 auto .4em}
.cta-band p{color:#cfe0d4;max-width:52ch;margin:0 auto 1.4em}
.cta-band .hero-cta{justify-content:center}
/* ---------- footer ---------- */
footer.site{background:var(--green-900);color:#c7d6cc;padding-top:56px}
.foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:30px;padding-bottom:34px;border-bottom:1px solid rgba(255,255,255,.12)}
@media (max-width:900px){.foot-top{grid-template-columns:1fr 1fr}}
@media (max-width:520px){.foot-top{grid-template-columns:1fr}}
.foot-brand img{height:56px;width:auto;margin-bottom:12px;background:#fff;border-radius:10px;padding:6px}
.foot-brand p{font-size:.9rem;margin-bottom:10px;max-width:38ch}
.foot-phone{font-family:var(--font-display);font-weight:700;font-size:1.25rem;color:#fff}
footer h4{color:#fff;font-size:.98rem;margin-bottom:12px}
footer ul{list-style:none}
footer ul li{margin-bottom:8px}
footer ul a{font-size:.9rem}
footer ul a:hover{color:var(--gold)}
.subs{font-size:.82rem;line-height:1.7;color:#9fb4a6}
.foot-bottom{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;padding:20px 0 26px}
.foot-legal{font-size:.78rem;color:#8fa598;max-width:70ch}
.built{display:inline-flex;align-items:center;gap:8px;font-size:.85rem;color:#c7d6cc}
.built b{color:var(--gold)}
.built-ico{width:22px;height:22px;border-radius:6px}
/* ---------- sticky mobile bar ---------- */
.mbar{position:fixed;left:0;right:0;bottom:0;z-index:800;display:none;grid-template-columns:1fr 1fr;gap:8px;padding:10px;background:rgba(18,47,34,.96);backdrop-filter:blur(8px)}
.mbar a{display:flex;align-items:center;justify-content:center;gap:7px;padding:.8em;border-radius:12px;font-family:var(--font-display);font-weight:600;font-size:.95rem}
.mbar .c{background:#fff;color:var(--green-800)}
.mbar .q{background:var(--gold);color:#000}
@media (max-width:720px){.mbar{display:grid}body{padding-bottom:70px}}
/* crumb */
.crumb{font-size:.82rem;color:#bcd2c2;margin-bottom:6px}
.crumb a:hover{color:#fff}
